///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List(일정추출 공시서식/상장서식/조건추출) 조회 실패 콜백 — 서버 오류 메시지를 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadError();
 */
scwin.dts_List_OnLoadError = function() {
    try {
        scwin.alert_error2(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 조회 완료 콜백 — 0건이면 목록을 비우고 총 건수와 경과시간을 표시한 뒤 조회 버튼 상태·이미지를 되돌린다.
 * @param {Number} rowcount 조회 결과 건수
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadCompleted(dts_List.getRowCount());
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {

            dts_List.removeAll();
        }
        textbox_1.setValue("총 " + rowcount + "건");
        scwin.dispTimer(textbox_1); // 경과시간 표시

        btn_Search.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadError
 * @description dts_List2(일정추출 배치/화면) 조회 실패 콜백 — 서버 오류 메시지를 알림으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List2_OnLoadError();
 */
scwin.dts_List2_OnLoadError = function() {
    try {
        scwin.alert_error2(dts_List2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 조회 완료 콜백 — 0건이면 목록을 비우고 총 건수를 표시한다.
 * @param {Number} rowcount 조회 결과 건수
 * @returns {void}
