 */
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {

            dts_List2.removeAll();
        }
        textbox_2.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description 일정추출 그리드 더블클릭 — 클릭된 행의 접수번호를 보관하고, 공시제목 컬럼이면 공시뷰어를, 그 외 컬럼(접수번호 제외)이면 일정추출 상세 팝업을 연다.
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_List_OnDblClick(0, "DOC_TITLE");
 */
scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅  
        scwin.setContnId(dts_List, row);
        if (colid === 'DOC_TITLE') {

            fn_OpenDisclViewer_MGT(scwin.g_ACPT_NO, 'ULDMGT80235.gfm');
        } else if (colid !== 'DOC_TITLE' && colid !== 'ACPT_NO') {
            // 팝업 오픈
            scwin.popupSchdlExtrcOpen();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.grd_List_OnDblClick" });
    }
};

