/**
 * @method
 * @name btn_Search_onclick
 * @description 조회 버튼 클릭 — 입력값 검증 후 일정추출 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Search_onclick(e);
 */
scwin.btn_Search_onclick = function(e) {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀다운로드 버튼 클릭 — 일정추출(공시서식/상장서식/조건추출) 그리드를 엑셀 파일로 저장한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Excel_onclick(e);
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        const file_name = "일정추출";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";

        grd_List.GridToOffice(file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.btn_Excel_onclick" });
    }
};

