    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name list
 * @description 일정추출(공시서식/상장서식/조건추출) 목록을 조회한다 — 조회 버튼을 잠그고 경과시간 측정을 시작한 뒤 sbm_dts_List를 실행하고 완료 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.list();
 */
scwin.list = async function() {
    btn_Search.setDisabled(false);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    scwin.gSDate = new Date();
    scwin.gSTimer = scwin.gSDate.getTime();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List_OnLoadCompleted(dts_List.getRowCount()); // 구 콜백 연결

};

/**
 * @method
 * @name list2
 * @description 일정추출(배치/화면) 목록을 조회한다 — sbm_dts_List2를 실행하고 완료 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.list2();
 */
scwin.list2 = async function() {
    const sbmOptions = {
        id : "sbm_dts_List2",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List2_OnLoadCompleted(dts_List2.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 추출일자 입력값에 현재날짜를 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setCode();
 */
scwin.setCode = function() {
    edt_Date.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};

/**
 * @method
 * @name validDateTodayCheck
 * @description 추출일자 당일 여부 검사(현재 검사 로직 없이 항상 true 반환).
 * @returns {Boolean} 항상 true
 * @hidden N
 * @example const isValid = scwin.validDateTodayCheck();
 */
scwin.validDateTodayCheck = function() {
    return true;
};

/**
 * @method
 * @name validCheck
 * @description 조회 조건 입력값을 검증한다 — 추출일자/추출시간(시작·종료)/시작·종료시간 순서/접수번호 자릿수를 확인하고 오류 시 알림 후 해당 입력으로 포커스를 이동한다.
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
 * @example if (!scwin.validCheck()) { return; }
 */
scwin.validCheck = function() {
    if (edt_Date.getValue().length < 8) {
        alert("[추출일자]를 올바르게 입력하세요.");

        edt_Date.focus();
        return false;
    }
    if (edt_StartTm.getValue().length < 4) {
        alert("[추출시간]을 올바르게 입력하세요.");

        edt_StartTm.focus();
        return false;
    }
    if (edt_EndTm.getValue().length < 4) {
        alert("[추출시간]을 올바르게 입력하세요.");

        edt_EndTm.focus();
        return false;
    }
    if (edt_StartTm.getValue() > edt_EndTm.getValue()) {
        alert("[시작시간]을 [종료시간] 이전으로 선택하세요.");

        edt_StartTm.focus();
        return false;
    }
    if (txb_ACPT_NO.getValue() !== "" && txb_ACPT_NO.getValue().length !== 14) {
        alert("[접수번호]를 올바르게 입력하세요.");

        txb_ACPT_NO.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 입력값 검증 후 일정추출 목록 2종(공시서식/상장서식/조건추출, 배치/화면)을 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {
    if (!scwin.validCheck()) {
        return;
    }
    scwin.list(); // 공시서식,상장서식,조건추출

    scwin.list2(); // 배치,화면

};

/**
 * @method
 * @name setContnId
 * @description 클릭된 행의 접수번호(ACPT_NO)를 전역 변수(g_ACPT_NO)에 보관한다.
 * @param {Object} obj 대상 데이터 리스트 객체
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.setContnId(dts_List, 0);
 */
scwin.setContnId = function(obj, row) {

    scwin.g_ACPT_NO = obj.getCellData(eval(row), "ACPT_NO");
};

/**
 * @method
 * @name popupSchdlExtrcOpen
 * @description 일정추출 상세(ULDMGT80236) 팝업을 다이얼로그 프레임으로 연다.
 * @returns {void}
 * @hidden N
 * @example scwin.popupSchdlExtrcOpen();
 */
scwin.popupSchdlExtrcOpen = function() {
    const usrp = "/sysmonitor/ULDMGT80236.gfm";
    const winTitle = "일정추출 상세";

    frame.CreateDialogFrame("viewer_pop", usrp, winTitle, 0, -120, 1352, 1000, "window");
    // frame.Provider('/').OuterWindow.window.open(usrp,  "viewer_pop",
    // 		"left=0,top=0,width=1750,height=965,resizable=yes,scrollbars=no,location=no,status=no");

};

/**
 * @method
 * @name dispTimer
 * @description 조회 경과시간을 계산해 대상 텍스트박스 값 뒤에 "(처리시간 : m 분 s초)" 형식으로 덧붙인다.
 * @param {Object} textbox 경과시간을 표시할 텍스트박스 컴포넌트
 * @returns {void}
 * @hidden N
 * @example scwin.dispTimer(textbox_1);
 */
scwin.dispTimer = function(textbox) {
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    const dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    const min = Math.round(dispTimer / 60, 2);
    const sec = Math.round(dispTimer % 60);

    // alert("처리시간 : " + min + " 분 " + sec + "초");

    textbox.value += " (처리시간 : " + min + " 분 " + sec + "초)";
};

/**
 * @method
 * @name alert_error2
 * @description 데이터셋의 서버 오류를 사용자정의 오류 유형별로 순회하며 알림으로 표시한다(코드 '0'은 임의로 떨군 INFO 메시지, 그 외는 코드 포함 에러 메시지).
 * @param {Object} dtsObj 서버 오류를 확인할 데이터셋 객체
 * @returns {void}
 * @hidden N
 * @example scwin.alert_error2(dts_List);
 */
scwin.alert_error2 = function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {

        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {

            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지

                alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지

                alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};

/**
 * @method
 * @name gform_onload
 * @description 화면 초기 로드 로직(원본 gform onload) — 추출일자 초기값을 설정하고 조회를 수행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    scwin.setCode();
    scwin.search();
};
